import json,re,hashlib
from pathlib import Path
P=Path('territory-data/raw'); rows=[]; events=[]
def add(state,name,seat,url,pub,role='Member',note=''):
 rows.append(dict(state=state,name=name,constituency=seat,source_url=url,source_name=pub,role=role,note=note,chamber='State House of Assembly'))
def an(name,seat,slug,role='Member',date='2026',extra=''):
 add('Anambra',name,seat,'https://anambrastate.gov.ng/'+slug+'/','Anambra State Government / Ministry of Information',role,'Named as serving in official report dated '+date+'. Partial assembly coverage; not a certified live register. '+extra)
s=(P/'cross-river-team-data.js').read_text()
for role,name,seat in re.findall(r'position:"([^"]+)",name:"([^"]+)",constituency:"([^"]+)"',s):
 if seat=='Ogoja':continue
 add('Cross River',name,seat,'https://www.crshoa.crossriverstate.gov.ng/members','Cross River State House of Assembly',role,'10th Assembly directory checked 2026-11-04. Ogoja omitted because this directory and the official statistics report identify different people. Row-level update dates are unavailable; roles are publisher-listed snapshots.')
