def evid(key,state,names,date,title,url,summary,category='Documented activity',qualification=''):
 matches=[r for r in rows if r['state']==state and r['name'] in names];assert len(matches)==len(names),(names,matches)
 events.append(dict(id=key,member_ids=['office-'+hashlib.sha256((r['chamber']+'|'+r['state']+'|'+r['name']).encode()).hexdigest()[:12] for r in matches],date=date,reference_year=int(date[:4]),title=title,category=category,source_url=url,source_name=matches[0]['source_name'],classification='published',level='state constituency / named representative',status='Officially reported activity',qualification='Official self-report; not an independent outcome audit or complete tenure total. '+qualification,summary=summary,attribution='Named person and state constituency reviewed against the linked official report.'))
