for r in rows:
 m=re.search(r'(?:dated |report of )(2026-\d\d-\d\d)',r['note'])
 r['source_date']=m[1] if m else None;r['reference_year']=2026
for e in events:
 e['date_basis']='publication date' if e['id'] in ['crossriver-budget-20241205','anambra-ai-training-20260927','anambra-road-motion-20260218','edo-ubth-20260924','ebonyi-debate-20260812','delta-retreat-20260312'] else 'event date explicitly reported by publisher'
 if e['id']=='crossriver-budget-20241205':e['source_name']='Cross River State Ministry of Information'
 if e['id'] in ['edo-ubth-20260924','ebonyi-debate-20260812']:
  e['status']='Government broadcaster report';e['qualification']=e['qualification'].replace('Official self-report','Named-person news report')
P.joinpath('southern-officials-next.json').write_text(json.dumps(rows,indent=2))
P.joinpath('southern-activity-next.json').write_text(json.dumps(events,indent=2))
print('rows',len(rows),'events',len(events))
